<script setup>
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, errorMessage } from '../services/api'
import { useAuthStore } from '../stores/auth'
import { useFeedbackStore } from '../stores/feedback'
const route = useRoute(); const router = useRouter(); const auth = useAuthStore(); const feedback = useFeedbackStore(); const data = ref(null); const status = ref(''); const note = ref(''); const saving = ref(false)
const money = v => `${Number(v || 0).toFixed(2)} €`
async function load() { try { data.value = (await api.get(`/orders/${route.params.id}`)).data; status.value = data.value.order.orderStatus } catch(e) { feedback.show(errorMessage(e), 'error') } }
async function changeStatus() { saving.value = true; try { const res = await api.patch(`/admin/orders/${route.params.id}/status`, { status: status.value, note: note.value }); data.value.order = res.data.order; await load(); feedback.show('Estado atualizado.') } catch(e) { feedback.show(errorMessage(e), 'error') } finally { saving.value = false } }
async function remove(){if(!await feedback.confirm(`Eliminar definitivamente a encomenda ${data.value.order.publicNumber}?`, 'Eliminar encomenda'))return;try{await api.delete(`/admin/orders/${data.value.order.publicNumber}`);feedback.show('Encomenda eliminada.');router.replace('/admin/encomendas')}catch(e){feedback.show(errorMessage(e),'error')}}
onMounted(load)
</script>
<template><div class="page"><v-btn :to="auth.isAdmin ? '/admin/encomendas' : '/encomendas'" variant="text" prepend-icon="mdi-arrow-left" class="mb-4">Voltar</v-btn><v-skeleton-loader v-if="!data" type="article, table" /><template v-else><div class="page-head"><div><h1>{{ data.order.publicNumber }}</h1><p>Criada em {{ new Date(data.order.createdAt).toLocaleString('pt-PT') }}</p></div><div class="d-flex flex-wrap ga-2"><v-btn :href="auth.isAdmin ? data.order.pdfUrl.replace('/me/', '/admin/') : data.order.pdfUrl" target="_blank" variant="tonal" prepend-icon="mdi-currency-eur">PDF com preços</v-btn><v-btn :href="auth.isAdmin ? data.order.pdfNoPricesUrl.replace('/me/', '/admin/') : data.order.pdfNoPricesUrl" target="_blank" variant="tonal" prepend-icon="mdi-eye-off-outline">PDF sem preços</v-btn><v-btn v-if="auth.isAdmin" color="error" variant="tonal" prepend-icon="mdi-delete-outline" @click="remove">Eliminar</v-btn><v-chip size="large" :color="data.order.orderStatus === 'pending' ? 'warning' : data.order.orderStatus === 'confirmed' ? 'success' : 'info'">{{ data.order.orderStatusLabel }}</v-chip></div></div>
  <v-row><v-col cols="12" lg="8"><v-card class="soft-card"><v-card-title class="pa-5">Produtos</v-card-title><v-table><thead><tr><th>Produto</th><th>Variante</th><th>Qtd.</th><th class="text-right">Total</th></tr></thead><tbody><tr v-for="item in data.order.items" :key="item.id"><td><b>{{ item.name }}</b><div class="text-caption">{{ item.ref }}</div></td><td>{{ [item.color,item.size].filter(Boolean).join(' · ') || '—' }}</td><td>{{ item.quantity }}</td><td class="text-right font-weight-bold">{{ money(item.lineTotal) }}</td></tr></tbody></v-table><v-divider /><div class="d-flex justify-end pa-5 text-h6">Total: <b class="ml-3">{{ money(data.order.total) }}</b></div></v-card></v-col>
    <v-col cols="12" lg="4"><v-card class="soft-card pa-5 mb-4"><div class="text-h6 font-weight-bold mb-4">Cliente</div><b>{{ data.order.customerName }}</b><div>{{ data.order.customerCompany }}</div><div class="text-medium-emphasis mt-3">{{ data.order.customerEmail }}<br>{{ data.order.customerPhone }}<br>{{ data.order.customerNif }}</div><div class="mt-3">{{ data.order.customerAddressLine1 }}<br>{{ data.order.customerPostalCode }} {{ data.order.customerCity }}</div></v-card>
      <v-card v-if="auth.isAdmin" class="soft-card pa-5"><div class="text-h6 font-weight-bold mb-4">Atualizar estado</div><v-select v-model="status" label="Estado" :items="[{title:'Pendente',value:'pending'},{title:'Confirmada',value:'confirmed'},{title:'Enviada',value:'shipped'}]" /><v-textarea v-model="note" label="Nota interna" rows="2" /><v-btn color="primary" block :loading="saving" @click="changeStatus">Guardar estado</v-btn></v-card></v-col></v-row>
  <v-card v-if="data.history.length" class="soft-card pa-5 mt-5"><div class="text-h6 font-weight-bold mb-4">Histórico</div><v-timeline side="end" density="compact"><v-timeline-item v-for="row in data.history" :key="row.id" dot-color="secondary" size="small"><b>{{ row.newStatusLabel || row.newStatus }}</b><div class="text-caption text-medium-emphasis">{{ new Date(row.changedAt).toLocaleString('pt-PT') }} · {{ row.changedByUsername }}</div><div v-if="row.note">{{ row.note }}</div></v-timeline-item></v-timeline></v-card></template></div></template>
